run(){ printf '=== INPUT: %s\n' "$(printf '%q' "$1")"; out=$(/workspace/dataset/test13_executable --a "$1" 2>&1); rc=$?; printf 'RC=%s\n' "$rc"; printf '%s\n' "$out" | cat -A; printf -- '---\n'; }
